forward-algorithm.pseudocode:
def forward(obs, states, pi, A, B):
    # alpha[t][s] = P(o1..ot, qt = s | λ)
    alpha = [{s: pi[s] * B[s][obs[0]] for s in states}]
    for t in range(1, len(obs)):
        prev, cur = alpha[-1], {}
        for j in states:  # 이전 모든 상태에서 합산(sum)
            total = sum(prev[i] * A[i][j] for i in states)
            cur[j] = total * B[j][obs[t]]
        alpha.append(cur)
    return sum(alpha[-1].values())  # P(O | λ)

forward-chaining.pseudocode:
def forward_chain(facts, rules, goal=None):
    facts = set(facts)
    changed = True
    while changed:
        changed = False
        for cond, concl in rules:  # IF cond(집합) THEN concl
            if cond <= facts and concl not in facts:
                facts.add(concl)  # 새 사실 추가(점화)
                changed = True
                if concl == goal:
                    return facts
    return facts  # 더 이상 추가할 사실 없음

