forward-pass.pseudocode:
def forward_pass(order, dur, preds):
    # order: 위상 정렬된 활동, preds[a]: 선행 활동 목록
    es, ef = {}, {}
    for a in order:
        # ES = 선행 활동 EF의 최댓값 (없으면 0)
        es[a] = max((ef[p] for p in preds[a]), default=0)
        ef[a] = es[a] + dur[a]  # EF = ES + 기간
    return es, ef, max(ef.values())  # 최소 완료시간

forwarding-information-base.pseudocode:
def lpm_lookup(fib, dst_ip):
    # fib: {(prefix, length): next_hop}, 주소는 32비트 정수 (IPv4)
    best, best_len = None, -1
    for (prefix, length), next_hop in fib.items():
        # 상위 length비트 마스크
        mask = ((1 << length) - 1) << (32 - length)
        if (dst_ip & mask) == (prefix & mask) and length > best_len:
            best, best_len = next_hop, length  # 더 긴 접두사 우선
    return best  # 0.0.0.0/0 기본 경로가 있으면 항상 일치
